const R:&str="/home/ubuntu/src/zopro-perf-work/chunk-grouping176";fn r(p:impl AsRef<Path>)->PathBuf{Path::new(R).join(p)}fn load(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0u8;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break;}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn main(){assert!(!r("combined-analysis.json").exists());let a=load(r("analysis.json"));let b=load(r("missing-six/analysis.json"));let m=load("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-30-g2-vector-sign-adoption176/artifacts/production-source-manifest.json");let mut exacts=Vec::new();let mut pin_count=0;let mut commands=0;for prefix in["","missing-six/"]{let base=r(prefix);for file in["native-pins.json","pins.json"]{for(p,h)in load(base.join(file)).as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());pin_count+=1;}}for(dir,plan)in[("native","native-plan.json"),("runs","plan.json")]{assert_eq!(load(base.join(format!("{dir}/result.json")))["status"],"complete");for step in load(base.join(plan))["steps"].as_array().unwrap(){let n=step["name"].as_str().unwrap();let e=load(base.join(format!("{dir}/{n}/exit.json")));assert_eq!(e["returncode"],0);assert_eq!(e["success"],true);for stream in["stdout","stderr"]{assert_eq!(hash(base.join(format!("{dir}/{n}/{stream}.log"))),e[format!("{stream}_sha256")]);}commands+=1;}}let audit=load(base.join("source-audit.json"));let mut exact=0;for(p,h)in m["source_files_sha256"].as_object().unwrap(){assert_eq!(hash(Path::new("/home/ubuntu/src/zk-tools/zopro").join(p)),h.as_str().unwrap());let bytes=fs::read(base.join("source").join(p)).unwrap();if format!("{:x}",Sha256::digest(&bytes))==h.as_str().unwrap(){exact+=1;continue;}let mut s=String::from_utf8(bytes).unwrap();if p=="crates/zopro-core/src/lib.rs"{for key in["lib_call","generic_call"]{if let Some(call)=audit[key].as_str(){assert_eq!(s.matches(call).count(),1);s=s.replacen(call,"",1);}}}else{assert_eq!(p,"crates/zopro-core/src/msm_affine.rs");s=s.strip_suffix(audit["msm_suffix"].as_str().unwrap()).unwrap().to_string();}assert_eq!(format!("{:x}",Sha256::digest(s.as_bytes())),h.as_str().unwrap());}assert_eq!(exact,174);exacts.push(exact);}
 assert_eq!(commands,36);let initial=load(r("prior-proof-sha256.json"));let mut ledger=initial.as_array().unwrap().iter().map(|v|v.as_str().unwrap().to_owned()).collect::<BTreeSet<_>>();assert_eq!(ledger.len(),29447);let mut inventory=Vec::new();for prefix in["","missing-six/"]{for v in load(r(format!("{prefix}proof-inventory.json"))).as_array().unwrap(){assert_eq!(v["verified"],true);assert!(ledger.insert(v["proof_sha256"].as_str().unwrap().to_owned()));inventory.push(v.clone());}}assert_eq!(ledger.len(),29461);let final_ledger=load(r("missing-six/proof-sha256-after.json")).as_array().unwrap().iter().map(|v|v.as_str().unwrap().to_owned()).collect::<BTreeSet<_>>();assert_eq!(ledger,final_ledger);let mut cases=BTreeMap::new();for source in[&a,&b]{for(k,v)in source["cases"].as_object().unwrap(){if !v.as_object().unwrap().is_empty(){assert!(cases.insert(k.clone(),v.clone()).is_none());}}}assert_eq!(cases.len(),8);let mut queries=0;for case in cases.values(){assert_eq!(case.as_object().unwrap().len(),2);for q in case.as_object().unwrap().values(){let n=q["n"].as_u64().unwrap();let zero=q["zeros"].as_u64().unwrap();let mut sizes=Vec::new();let mut members=0;let mut instances=0;for row in q["class_histogram_count_chunks_span_category_classes"].as_array().unwrap(){for _ in 0..row[4].as_u64().unwrap(){members+=row[0].as_u64().unwrap();instances+=row[1].as_u64().unwrap();sizes.push(row[1].as_u64().unwrap());}}assert_eq!(members+zero,n);let distinct=sizes.len()as u64;assert_eq!(q["distinct_nonzero"],distinct);assert_eq!(q["local_distinct_sum"],instances);assert_eq!(q["per_chunk_distinct"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()).sum::<u64>(),instances);assert_eq!(q["extra_chunk_class_instances"],instances-distinct);sizes.sort_unstable_by(|a,b|b.cmp(a));for(i,k)in[8usize,16,32].into_iter().enumerate(){let extra=sizes.iter().take(k).sum::<u64>()-k.min(sizes.len())as u64;assert_eq!(q["save_class_instances_top8_16_32"][i],extra);}queries+=1;}}
 assert_eq!(queries,16);assert_eq!(load(r("native/core-ON/tests.json"))["passed_tests"].as_array().unwrap().len(),128);assert_eq!(load(r("native/core-ON/tests.json"))["unfiltered"],true);assert_eq!(load(r("missing-six/native/core-ON/tests.json"))["passed_tests"].as_array().unwrap().len(),4);assert_eq!(load(r("missing-six/native/core-ON/tests.json"))["unfiltered"],false);
 let review=json!({"passed":true,"pin_entries_checked":pin_count,"successful_commands":commands,"source_originals_recovered_each":176,"source_originals_exact_each":exacts,"all8circuits_16query_counts_independently_recomputed":true,"native_core_original_full":128,"native_missing_six_focused":4,"prior_ledger":29447,"fresh_Gnark_exports":14,"proof_ledger":29461,"coverage_failure_retained":true,"production_changed":false,"performance_inference":false,"adopted":false});let result=json!({"complete":true,"cases":cases,"SDK_requests":14,"fresh_Gnark_exports":14,"prior_ledger":29447,"proof_ledger":29461,"review":review,"first_capture_observed_shapes":2,"second_capture_missing_shapes":6,"first_finisher_failed_coverage_assertion":true,"production_changed":false,"adopted":false,"goal_achieved":false,"new_performance_claim":false});fs::write(r("combined-analysis.json"),serde_json::to_vec_pretty(&result).unwrap()).unwrap();fs::write(r("review.json"),serde_json::to_vec_pretty(&review).unwrap()).unwrap();fs::write(r("combined-proof-inventory.json"),serde_json::to_vec_pretty(&inventory).unwrap()).unwrap();println!("{review}");}
